package com.suiren.mirea.playback;
import org.json.*;
/** Plain-text captions; navigation remains in RAM and follows current ACLs. */
public final class VideoNavigation {
    public static String caption(JSONObject nav,String selected,long position){if(nav==null||"off".equals(selected))return "";JSONArray tracks=nav.optJSONArray("captions");if(tracks==null)return "";JSONObject track=null;for(int n=0;n<tracks.length();n++){JSONObject t=tracks.optJSONObject(n);if(t!=null&&(selected.equals(t.optString("id"))||track==null&&selected.equals(t.optString("language"))))track=t;}if(track==null)return "";JSONArray cues=track.optJSONArray("cues");if(cues==null)return "";StringBuilder text=new StringBuilder();for(int n=0;n<cues.length();n++){JSONObject c=cues.optJSONObject(n);if(c==null)continue;if(c.optLong("startMs")>position)break;if(c.optLong("endMs")>position){if(text.length()>0)text.append('\n');text.append(c.optString("text"));if(text.length()>2000)break;}}return text.toString();}
    public static String chapter(JSONObject nav,long position){if(nav==null)return "";JSONArray list=nav.optJSONArray("chapters");String value="";if(list!=null)for(int n=0;n<list.length();n++){JSONObject c=list.optJSONObject(n);if(c!=null&&c.optLong("startMs")<=position)value=c.optString("title");}return value;}
    public static long chapterPosition(JSONObject nav,long position,int direction){if(nav==null)return position;JSONArray list=nav.optJSONArray("chapters");if(list==null)return position;if(direction>0){for(int n=0;n<list.length();n++){JSONObject c=list.optJSONObject(n);if(c!=null&&c.optLong("startMs")>position+500)return c.optLong("startMs");}return position;}long target=0;for(int n=0;n<list.length();n++){JSONObject c=list.optJSONObject(n);if(c!=null&&c.optLong("startMs")<position-1500)target=c.optLong("startMs");}return target;}
}
